package quarry.client;

import java.util.HashMap;
import java.util.Map;

/** Иконки интерфейса (шестерёнка, палитра, лупа): маски 64x64, 16 уровней прозрачности. Красятся в любой цвет и гладко масштабируются. */
public final class Glyphs {
    private static final int N = 64;
    private static final Map<String, String> MASKS = new HashMap<>();
    private static final Map<String, int[]> CACHE = new HashMap<>();

    static {
        MASKS.put("gear", "");
        MASKS.put("palette", "");
        MASKS.put("search", "");
    }

    /** Уровни прозрачности 0..15 для квадрата size x size физических пикселей (с усреднением, чтобы края были гладкими). */
    public static int[] sample(String name, int size) {
        String key = name + ":" + size;
        int[] r = CACHE.get(key);
        if (r != null) return r;
        String m = MASKS.get(name);
        if (m == null) return null;
        r = new int[size * size];
        int ss = 3;
        for (int py = 0; py < size; py++) {
            for (int px = 0; px < size; px++) {
                double sum = 0;
                for (int sy = 0; sy < ss; sy++) {
                    for (int sx = 0; sx < ss; sx++) {
                        int mx = Math.min(N - 1, (int) ((px + (sx + 0.5) / ss) * N / size));
                        int my = Math.min(N - 1, (int) ((py + (sy + 0.5) / ss) * N / size));
                        sum += Character.digit(m.charAt(my * N + mx), 16);
                    }
                }
                r[py * size + px] = (int) Math.round(sum / (ss * ss));
            }
        }
        CACHE.put(key, r);
        return r;
    }
}
